"""
    Finds all unique pairs of integers in the list that add up to the target sum.

    :param nums: List[int] - A list of integers.
    :param target: int - The target sum for the pairs.
    :return: List[List[int]] - A list of lists containing the pair indices and their sums.
    """
    num_dict = {}
    for index, value in enumerate(nums):
        complement = target - value
        if complement in num_dict:
            pair = (min(index, num_dict[complement]), max(index, num_dict[complement]))
            if pair not in pairs:
                pairs.append(pair)
        else:
            num_dict[value] = True
    return pairs

